// Package rapidmlx wraps the OpenAI-compatible HTTP surface exposed by
// Rapid-MLX (https://github.com/raullenchai/Rapid-MLX). It is a concrete
// provider type distinct from vLLM so the service layer can keep provider
// identity separate from utilization probing, which Rapid-MLX exposes on a
// different observability endpoint family.
package rapidmlx

import (
	agentcore "github.com/DocumentDrivenDX/fizeau/internal/core"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/openai"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/registry"
	"github.com/DocumentDrivenDX/fizeau/internal/reasoning"
)

const DefaultBaseURL = "http://localhost:8000/v1"

func init() {
	registry.Register(registry.Descriptor{
		Type: "rapid-mlx",
		Factory: func(in registry.Inputs) agentcore.Provider {
			return New(Config{
				BaseURL:      in.BaseURL,
				APIKey:       in.APIKey,
				Model:        in.Model,
				ModelPattern: in.ModelPattern,
				KnownModels:  in.KnownModels,
				Headers:      in.Headers,
				Reasoning:    in.Reasoning,
			})
		},
		DefaultBaseURL: DefaultBaseURL,
		DefaultPort:    8000,
	})
}

// ProtocolCapabilities keeps Rapid-MLX on the standard OpenAI-compatible
// surface. The provider remains distinct from vLLM at the type level.
var ProtocolCapabilities = openai.OpenAIProtocolCapabilities

type Config struct {
	BaseURL      string
	APIKey       string
	Model        string
	ModelPattern string
	KnownModels  map[string]string
	Headers      map[string]string
	Reasoning    reasoning.Reasoning
}

func New(cfg Config) *openai.Provider {
	baseURL := cfg.BaseURL
	if baseURL == "" {
		baseURL = DefaultBaseURL
	}
	return openai.New(openai.Config{
		BaseURL:        baseURL,
		APIKey:         cfg.APIKey,
		Model:          cfg.Model,
		ProviderName:   "rapid-mlx",
		ProviderSystem: "rapid-mlx",
		ModelPattern:   cfg.ModelPattern,
		KnownModels:    cfg.KnownModels,
		Headers:        cfg.Headers,
		Reasoning:      cfg.Reasoning,
		Capabilities:   &ProtocolCapabilities,
	})
}

package utilization

import (
	"net/url"
	"strconv"
	"strings"
	"sync"
	"time"
)

// Source identifies the probe path that produced a utilization sample.
type Source string

const (
	SourceUnknown      Source = "unknown"
	SourceVLLMMetrics  Source = "vllm.metrics"
	SourceLlamaMetrics Source = "llama-server.metrics"
	SourceLlamaSlots   Source = "llama-server.slots"
)

// Freshness describes whether a sample was observed just now, reused after a
// failed probe, or has no known prior observation.
type Freshness string

const (
	FreshnessFresh   Freshness = "fresh"
	FreshnessStale   Freshness = "stale"
	FreshnessUnknown Freshness = "unknown"
)

// EndpointUtilization is the normalized utilization shape shared by local
// provider probes.
type EndpointUtilization struct {
	ActiveRequests *int
	QueuedRequests *int
	CacheUsage     *float64
	MaxConcurrency *int
	Source         Source
	Freshness      Freshness
	ObservedAt     time.Time
}

// Cache preserves the most recent successful sample so probe failures can
// return stale utilization instead of surfacing hard endpoint unavailability.
type Cache struct {
	mu   sync.Mutex
	last *EndpointUtilization
}

// Remember stores a fresh sample and returns a normalized copy with fresh
// freshness and an observed timestamp.
func (c *Cache) Remember(sample EndpointUtilization) EndpointUtilization {
	c.mu.Lock()
	defer c.mu.Unlock()

	now := time.Now().UTC()
	sample.Freshness = FreshnessFresh
	sample.ObservedAt = now
	stored := clone(sample)
	c.last = &stored
	return stored
}

// Stale returns the last successful sample marked stale. The boolean reports
// whether a previous sample existed.
func (c *Cache) Stale() (EndpointUtilization, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if c.last == nil {
		return EndpointUtilization{}, false
	}
	stale := clone(*c.last)
	stale.Freshness = FreshnessStale
	return stale, true
}

// Unknown returns a sample with unknown freshness and no numeric values.
func Unknown(source Source) EndpointUtilization {
	return EndpointUtilization{
		Source:    source,
		Freshness: FreshnessUnknown,
	}
}

// Int returns a pointer to v.
func Int(v int) *int {
	return &v
}

// Float64 returns a pointer to v.
func Float64(v float64) *float64 {
	return &v
}

// ServerRoot strips a trailing /v1 path component from an OpenAI-compatible
// base URL while preserving the scheme, host, and any prefix path.
func ServerRoot(baseURL string) string {
	trimmed := strings.TrimSpace(strings.TrimRight(baseURL, "/"))
	if trimmed == "" {
		return ""
	}

	parsed, err := url.Parse(trimmed)
	if err != nil {
		return strings.TrimSuffix(trimmed, "/v1")
	}

	parsed.Fragment = ""
	parsed.RawQuery = ""
	path := strings.TrimRight(parsed.Path, "/")
	if strings.HasSuffix(path, "/v1") {
		path = strings.TrimSuffix(path, "/v1")
	}
	parsed.Path = path
	return strings.TrimRight(parsed.String(), "/")
}

// ParsePrometheusMetricValue returns the first numeric value for metric from
// a Prometheus-style plaintext metrics body.
func ParsePrometheusMetricValue(body, metric string) (float64, bool) {
	for _, line := range strings.Split(body, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") || !strings.HasPrefix(line, metric) {
			continue
		}
		rest := strings.TrimSpace(strings.TrimPrefix(line, metric))
		if strings.HasPrefix(rest, "{") {
			if idx := strings.Index(rest, "}"); idx >= 0 {
				rest = strings.TrimSpace(rest[idx+1:])
			}
		}
		fields := strings.Fields(rest)
		if len(fields) == 0 {
			continue
		}
		val, err := strconv.ParseFloat(fields[0], 64)
		if err == nil {
			return val, true
		}
	}
	return 0, false
}

func clone(sample EndpointUtilization) EndpointUtilization {
	out := sample
	if sample.ActiveRequests != nil {
		out.ActiveRequests = Int(*sample.ActiveRequests)
	}
	if sample.QueuedRequests != nil {
		out.QueuedRequests = Int(*sample.QueuedRequests)
	}
	if sample.CacheUsage != nil {
		out.CacheUsage = Float64(*sample.CacheUsage)
	}
	if sample.MaxConcurrency != nil {
		out.MaxConcurrency = Int(*sample.MaxConcurrency)
	}
	return out
}

package vllm

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"strings"

	"github.com/DocumentDrivenDX/fizeau/internal/provider/utilization"
)

// UtilizationProbe queries vLLM server-root observability endpoints and
// normalizes them into the shared endpoint utilization shape.
type UtilizationProbe struct {
	baseURL string
	client  *http.Client
	cache   utilization.Cache
}

// NewUtilizationProbe creates a probe for an OpenAI-compatible vLLM base URL.
func NewUtilizationProbe(baseURL string, client *http.Client) *UtilizationProbe {
	if client == nil {
		client = http.DefaultClient
	}
	return &UtilizationProbe{
		baseURL: baseURL,
		client:  client,
	}
}

// Probe fetches /metrics from the server root and returns a normalized sample.
// Failures return stale or unknown utilization instead of surfacing endpoint
// unavailability.
func (p *UtilizationProbe) Probe(ctx context.Context) utilization.EndpointUtilization {
	body, err := p.get(ctx, utilization.ServerRoot(p.baseURL)+"/metrics")
	if err != nil {
		if stale, ok := p.cache.Stale(); ok {
			return stale
		}
		return utilization.Unknown(utilization.SourceVLLMMetrics)
	}

	running, ok := utilization.ParsePrometheusMetricValue(body, "vllm:num_requests_running")
	if !ok {
		if stale, ok := p.cache.Stale(); ok {
			return stale
		}
		return utilization.Unknown(utilization.SourceVLLMMetrics)
	}
	waiting, ok := utilization.ParsePrometheusMetricValue(body, "vllm:num_requests_waiting")
	if !ok {
		if stale, ok := p.cache.Stale(); ok {
			return stale
		}
		return utilization.Unknown(utilization.SourceVLLMMetrics)
	}

	sample := utilization.EndpointUtilization{
		ActiveRequests: utilization.Int(int(running)),
		QueuedRequests: utilization.Int(int(waiting)),
		Source:         utilization.SourceVLLMMetrics,
	}
	if cacheUsage, ok := utilization.ParsePrometheusMetricValue(body, "vllm:kv_cache_usage_perc"); ok {
		sample.CacheUsage = utilization.Float64(cacheUsage)
	} else if cacheUsage, ok := utilization.ParsePrometheusMetricValue(body, "vllm:gpu_cache_usage_perc"); ok {
		sample.CacheUsage = utilization.Float64(cacheUsage)
	}
	return p.cache.Remember(sample)
}

func (p *UtilizationProbe) get(ctx context.Context, endpoint string) (string, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
	if err != nil {
		return "", err
	}
	resp, err := p.client.Do(req)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 256))
		return "", fmt.Errorf("HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
	}
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return "", err
	}
	return string(body), nil
}

package llamaserver

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"

	"github.com/DocumentDrivenDX/fizeau/internal/provider/utilization"
)

// UtilizationProbe queries llama-server observability endpoints and
// normalizes them into the shared endpoint utilization shape.
type UtilizationProbe struct {
	baseURL string
	client  *http.Client
	cache   utilization.Cache
}

// NewUtilizationProbe creates a probe for an OpenAI-compatible llama-server
// base URL.
func NewUtilizationProbe(baseURL string, client *http.Client) *UtilizationProbe {
	if client == nil {
		client = http.DefaultClient
	}
	return &UtilizationProbe{
		baseURL: baseURL,
		client:  client,
	}
}

// Probe first tries /metrics on the server root and falls back to /slots when
// metrics are unavailable.
func (p *UtilizationProbe) Probe(ctx context.Context) utilization.EndpointUtilization {
	if sample, ok := p.probeMetrics(ctx); ok {
		return p.cache.Remember(sample)
	}
	if sample, ok := p.probeSlots(ctx); ok {
		return p.cache.Remember(sample)
	}
	if stale, ok := p.cache.Stale(); ok {
		return stale
	}
	return utilization.Unknown(utilization.SourceLlamaMetrics)
}

func (p *UtilizationProbe) probeMetrics(ctx context.Context) (utilization.EndpointUtilization, bool) {
	body, err := p.get(ctx, utilization.ServerRoot(p.baseURL)+"/metrics")
	if err != nil {
		return utilization.EndpointUtilization{}, false
	}

	processing, ok := utilization.ParsePrometheusMetricValue(body, "llamacpp:requests_processing")
	if !ok {
		return utilization.EndpointUtilization{}, false
	}
	deferred, ok := utilization.ParsePrometheusMetricValue(body, "llamacpp:requests_deferred")
	if !ok {
		return utilization.EndpointUtilization{}, false
	}

	sample := utilization.EndpointUtilization{
		ActiveRequests: utilization.Int(int(processing)),
		QueuedRequests: utilization.Int(int(deferred)),
		Source:         utilization.SourceLlamaMetrics,
	}
	if cacheUsage, ok := utilization.ParsePrometheusMetricValue(body, "llamacpp:kv_cache_usage_ratio"); ok {
		sample.CacheUsage = utilization.Float64(cacheUsage)
	}
	return sample, true
}

func (p *UtilizationProbe) probeSlots(ctx context.Context) (utilization.EndpointUtilization, bool) {
	body, err := p.get(ctx, utilization.ServerRoot(p.baseURL)+"/slots")
	if err != nil {
		return utilization.EndpointUtilization{}, false
	}

	var arrayPayload []map[string]any
	slots := 0
	processing := 0
	if err := json.Unmarshal([]byte(strings.TrimSpace(body)), &arrayPayload); err == nil {
		slots = len(arrayPayload)
		for _, slot := range arrayPayload {
			if isProcessing(slot) {
				processing++
			}
		}
		return p.slotSample(processing, slots), true
	}

	var objectPayload struct {
		Slots     []map[string]any `json:"slots"`
		SlotCount int              `json:"slot_count"`
	}
	if err := json.Unmarshal([]byte(strings.TrimSpace(body)), &objectPayload); err != nil {
		return utilization.EndpointUtilization{}, false
	}
	slots = objectPayload.SlotCount
	if slots == 0 {
		slots = len(objectPayload.Slots)
	}
	for _, slot := range objectPayload.Slots {
		if isProcessing(slot) {
			processing++
		}
	}
	return p.slotSample(processing, slots), true
}

func (p *UtilizationProbe) slotSample(processing, slots int) utilization.EndpointUtilization {
	sample := utilization.EndpointUtilization{
		ActiveRequests: utilization.Int(processing),
		Source:         utilization.SourceLlamaSlots,
	}
	if slots > 0 {
		sample.MaxConcurrency = utilization.Int(slots)
		occupancy := float64(processing) / float64(slots)
		sample.CacheUsage = utilization.Float64(occupancy)
	}
	return sample
}

func isProcessing(slot map[string]any) bool {
	processing, _ := slot["is_processing"].(bool)
	return processing
}

func (p *UtilizationProbe) get(ctx context.Context, endpoint string) (string, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
	if err != nil {
		return "", err
	}
	resp, err := p.client.Do(req)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 256))
		return "", fmt.Errorf("HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
	}
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return "", err
	}
	return string(body), nil
}

package llamaserver

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/provider/testutil"
	"github.com/stretchr/testify/require"
	"gopkg.in/dnaeon/go-vcr.v4/pkg/recorder"
)

const (
	llamaCassetteName      = "llama_server_utilization"
	llamaRecordImage       = "ghcr.io/ggml-org/llama.cpp:server"
	llamaRecordRepo        = "QuantFactory/tinyllama-15M-alpaca-finetuned-GGUF"
	llamaRecordFile        = "tinyllama-15M-alpaca-finetuned.Q4_K_M.gguf"
	llamaRecordPrompt      = "Reply with one short word."
	llamaBusyPrompt        = "Write a 200-word paragraph about a small robot."
	llamaRequestMaxTokens  = 8
	llamaBusyRequestTokens = 64
)

type llamaMetricsSnapshot struct {
	RequestsProcessing int
	RequestsDeferred   int
	KVCacheUsageRatio  float64
}

type llamaSlotsSnapshot struct {
	SlotCount       int
	ProcessingSlots int
}

type llamaChatMessage struct {
	Content string `json:"content"`
	Role    string `json:"role"`
}

func TestLlamaServerCassetteAndUtilization(t *testing.T) {
	cassettePath := testutil.CassettePath(filepath.Join("testdata", "cassettes"), llamaCassetteName)

	rec, err := testutil.NewRecorder(cassettePath)
	require.NoError(t, err)
	client := rec.GetDefaultClient()
	t.Cleanup(func() {
		require.NoError(t, rec.Stop())
	})

	if testutil.ModeForEnvironment() == recorder.ModeRecordOnly {
		srv := mustStartLlamaServer(t)
		t.Cleanup(srv.Stop)

		recordInteractions(t, client, srv.BaseURL, srv.DirectClient, true)
		return
	}

	recordInteractions(t, client, "http://replay.invalid/v1", http.DefaultClient, false)
}

func TestLlamaServerUtilization_ParseMetricsAndSlots(t *testing.T) {
	metricSamples := []struct {
		name string
		body string
		want llamaMetricsSnapshot
	}{
		{
			name: "metrics snapshot",
			body: strings.Join([]string{
				"# HELP llamacpp:requests_processing Number of requests processing.",
				"llamacpp:requests_processing 1",
				"llamacpp:requests_deferred 2",
				"llamacpp:kv_cache_usage_ratio 0.375",
			}, "\n"),
			want: llamaMetricsSnapshot{
				RequestsProcessing: 1,
				RequestsDeferred:   2,
				KVCacheUsageRatio:  0.375,
			},
		},
	}

	for _, tc := range metricSamples {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			got, err := parseLlamaMetrics(tc.body)
			require.NoError(t, err)
			require.Equal(t, tc.want.RequestsProcessing, got.RequestsProcessing)
			require.Equal(t, tc.want.RequestsDeferred, got.RequestsDeferred)
			require.InDelta(t, tc.want.KVCacheUsageRatio, got.KVCacheUsageRatio, 1e-6)
		})
	}

	slotSamples := []struct {
		name string
		body string
		want llamaSlotsSnapshot
	}{
		{
			name: "array payload",
			body: `[
  {"id":0,"id_task":101,"is_processing":true},
  {"id":1,"id_task":102,"is_processing":false}
]`,
			want: llamaSlotsSnapshot{
				SlotCount:       2,
				ProcessingSlots: 1,
			},
		},
		{
			name: "object payload",
			body: `{"slots":[{"is_processing":true},{"is_processing":true}],"slot_count":2}`,
			want: llamaSlotsSnapshot{
				SlotCount:       2,
				ProcessingSlots: 2,
			},
		},
	}

	for _, tc := range slotSamples {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			got, err := parseLlamaSlots(tc.body)
			require.NoError(t, err)
			require.Equal(t, tc.want.SlotCount, got.SlotCount)
			require.Equal(t, tc.want.ProcessingSlots, got.ProcessingSlots)
		})
	}
}

func recordInteractions(t *testing.T, client *http.Client, baseURL string, probeClient *http.Client, recordMode bool) {
	t.Helper()
	rootURL := serverRootURL(baseURL)
	models := fetchModels(t, client, baseURL)
	require.NotEmpty(t, models)
	model := models[0]

	idleMetrics := fetchMetrics(t, client, rootURL)
	require.GreaterOrEqual(t, idleMetrics.RequestsProcessing, 0)
	require.GreaterOrEqual(t, idleMetrics.RequestsDeferred, 0)

	idleSlots := fetchSlots(t, client, rootURL)
	require.GreaterOrEqual(t, idleSlots.SlotCount, 1)
	require.Equal(t, 0, idleSlots.ProcessingSlots)

	minimalChat := chatCompletion(t, client, baseURL, model, llamaRecordPrompt, llamaRequestMaxTokens)
	require.NotEmpty(t, minimalChat)

	if recordMode {
		busyResp := startStreamingChat(t, probeClient, baseURL, model, llamaBusyPrompt, llamaBusyRequestTokens)
		t.Cleanup(func() {
			if busyResp != nil && busyResp.Body != nil {
				_, _ = io.Copy(io.Discard, busyResp.Body)
				_ = busyResp.Body.Close()
			}
		})

		waitForLlamaMetrics(t, probeClient, rootURL, func(s llamaMetricsSnapshot) bool {
			return s.RequestsProcessing > 0
		})
	}

	busyMetrics := fetchMetrics(t, client, rootURL)
	require.GreaterOrEqual(t, busyMetrics.RequestsProcessing, 1)

	busySlots := fetchSlots(t, client, rootURL)
	require.GreaterOrEqual(t, busySlots.ProcessingSlots, 1)
	require.GreaterOrEqual(t, busySlots.SlotCount, busySlots.ProcessingSlots)

	busyUtilization := combineLlamaUtilization(busyMetrics, busySlots)
	require.Greater(t, busyUtilization.KVCacheUsageRatio, 0.0)
}

func fetchModels(t *testing.T, client *http.Client, baseURL string) []string {
	t.Helper()
	req, err := http.NewRequest(http.MethodGet, strings.TrimRight(baseURL, "/")+"/models", nil)
	require.NoError(t, err)
	resp, err := client.Do(req)
	require.NoError(t, err)
	defer resp.Body.Close()
	require.NoError(t, statusOK(resp.StatusCode))

	var payload struct {
		Data []struct {
			ID string `json:"id"`
		} `json:"data"`
	}
	require.NoError(t, json.NewDecoder(resp.Body).Decode(&payload))
	models := make([]string, 0, len(payload.Data))
	for _, entry := range payload.Data {
		if entry.ID != "" {
			models = append(models, entry.ID)
		}
	}
	return models
}

func fetchMetrics(t *testing.T, client *http.Client, baseURL string) llamaMetricsSnapshot {
	t.Helper()
	req, err := http.NewRequest(http.MethodGet, strings.TrimRight(baseURL, "/")+"/metrics", nil)
	require.NoError(t, err)
	resp, err := client.Do(req)
	require.NoError(t, err)
	defer resp.Body.Close()
	require.NoError(t, statusOK(resp.StatusCode))

	body, err := io.ReadAll(resp.Body)
	require.NoError(t, err)
	snap, err := parseLlamaMetrics(string(body))
	require.NoError(t, err)
	return snap
}

func fetchSlots(t *testing.T, client *http.Client, baseURL string) llamaSlotsSnapshot {
	t.Helper()
	req, err := http.NewRequest(http.MethodGet, strings.TrimRight(baseURL, "/")+"/slots", nil)
	require.NoError(t, err)
	resp, err := client.Do(req)
	require.NoError(t, err)
	defer resp.Body.Close()
	require.NoError(t, statusOK(resp.StatusCode))

	body, err := io.ReadAll(resp.Body)
	require.NoError(t, err)
	snap, err := parseLlamaSlots(string(body))
	require.NoError(t, err)
	return snap
}

func chatCompletion(t *testing.T, client *http.Client, baseURL, model, prompt string, maxTokens int) string {
	t.Helper()
	content, err := chatCompletionRaw(client, baseURL, model, prompt, maxTokens)
	require.NoError(t, err)
	return content
}

func startStreamingChat(t *testing.T, client *http.Client, baseURL, model, prompt string, maxTokens int) *http.Response {
	t.Helper()
	resp, err := startStreamingChatRaw(client, baseURL, model, prompt, maxTokens)
	require.NoError(t, err)
	return resp
}

func chatCompletionRaw(client *http.Client, baseURL, model, prompt string, maxTokens int) (string, error) {
	body := struct {
		MaxTokens   int                `json:"max_tokens"`
		Messages    []llamaChatMessage `json:"messages"`
		Model       string             `json:"model"`
		Temperature int                `json:"temperature"`
	}{
		MaxTokens:   maxTokens,
		Messages:    []llamaChatMessage{{Content: prompt, Role: "user"}},
		Model:       model,
		Temperature: 0,
	}
	raw, err := json.Marshal(body)
	if err != nil {
		return "", err
	}

	req, err := http.NewRequest(http.MethodPost, strings.TrimRight(baseURL, "/")+"/chat/completions", strings.NewReader(string(raw)))
	if err != nil {
		return "", err
	}
	req.Header.Set("Content-Type", "application/json")

	resp, err := client.Do(req)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	if err := statusOK(resp.StatusCode); err != nil {
		return "", err
	}

	var payload struct {
		Choices []struct {
			Message struct {
				Content string `json:"content"`
			} `json:"message"`
		} `json:"choices"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&payload); err != nil {
		return "", err
	}
	if len(payload.Choices) == 0 {
		return "", fmt.Errorf("chat completion returned no choices")
	}
	return payload.Choices[0].Message.Content, nil
}

func startStreamingChatRaw(client *http.Client, baseURL, model, prompt string, maxTokens int) (*http.Response, error) {
	body := struct {
		MaxTokens   int                `json:"max_tokens"`
		Messages    []llamaChatMessage `json:"messages"`
		Model       string             `json:"model"`
		Temperature int                `json:"temperature"`
		Stream      bool               `json:"stream"`
	}{
		MaxTokens:   maxTokens,
