 16	// UtilizationProbe queries Rapid-MLX status endpoints and normalizes them into
 17	// the shared endpoint utilization shape.
 18	type UtilizationProbe struct {
 19		baseURL string
 20		client  *http.Client
 21		cache   utilization.Cache
 22	}
