 51	func (p *UtilizationProbe) probeStatus(ctx context.Context) (rapidMLXStatusSnapshot, bool) {
 52		body, err := p.get(ctx, utilization.ServerRoot(p.baseURL)+"/status")
 53		if err != nil {
 54			return rapidMLXStatusSnapshot{}, false
 55		}
 56	
 57		snapshot, err := parseRapidMLXStatus(body)
 58		if err != nil {
 59			return rapidMLXStatusSnapshot{}, false
 60		}
 61		return snapshot, true
 62	}
