 24	type Freshness string
 25	
 26	const (
 27		FreshnessFresh   Freshness = "fresh"
 28		FreshnessStale   Freshness = "stale"
 29		FreshnessUnknown Freshness = "unknown"
 30	)
 31	
 32	// EndpointUtilization is the normalized utilization shape shared by local
 33	// provider probes.
 34	type EndpointUtilization struct {
 35		ActiveRequests         *int
 36		QueuedRequests         *int
 37		CacheUsage             *float64
 38		MaxConcurrency         *int
 39		TotalPromptTokens      *int
 40		TotalCompletionTokens  *int
