 49		MetalCacheMemoryBytes  *int64
 50		Source                 Source
 51		Freshness              Freshness
 52		ObservedAt             time.Time
 53	}
 54	
 55	// Cache preserves the most recent successful sample so probe failures can
 56	// return stale utilization instead of surfacing hard endpoint unavailability.
 57	type Cache struct {
 58		mu   sync.Mutex
 59		last *EndpointUtilization
 60	}
 61	
 62	// Remember stores a fresh sample and returns a normalized copy with fresh
 63	// freshness and an observed timestamp.
 64	func (c *Cache) Remember(sample EndpointUtilization) EndpointUtilization {
 65		c.mu.Lock()
 66		defer c.mu.Unlock()
 67	
 68		now := time.Now().UTC()
 69		sample.Freshness = FreshnessFresh
 70		sample.ObservedAt = now
 71		stored := clone(sample)
 72		c.last = &stored
 73		return stored
 74	}
 75	
 76	// Stale returns the last successful sample marked stale. The boolean reports
 77	// whether a previous sample existed.
 78	func (c *Cache) Stale() (EndpointUtilization, bool) {
 79		c.mu.Lock()
 80		defer c.mu.Unlock()
 81	
 82		if c.last == nil {
 83			return EndpointUtilization{}, false
 84		}
 85		stale := clone(*c.last)
 86		stale.Freshness = FreshnessStale
 87		return stale, true
 88	}
