118	// ServerRoot strips a trailing /v1 path component from an OpenAI-compatible
119	// base URL while preserving the scheme, host, and any prefix path.
120	func ServerRoot(baseURL string) string {
121		trimmed := strings.TrimSpace(strings.TrimRight(baseURL, "/"))
122		if trimmed == "" {
123			return ""
124		}
125	
126		parsed, err := url.Parse(trimmed)
127		if err != nil {
128			return strings.TrimSuffix(trimmed, "/v1")
129		}
130	
131		parsed.Fragment = ""
132		parsed.RawQuery = ""
133		path := strings.TrimRight(parsed.Path, "/")
134		if strings.HasSuffix(path, "/v1") {
135			path = strings.TrimSuffix(path, "/v1")
136		}
137		parsed.Path = path
138		return strings.TrimRight(parsed.String(), "/")
139	}
