141	// ParsePrometheusMetricValue returns the first numeric value for metric from
142	// a Prometheus-style plaintext metrics body.
143	func ParsePrometheusMetricValue(body, metric string) (float64, bool) {
144		for _, line := range strings.Split(body, "\n") {
145			line = strings.TrimSpace(line)
146			if line == "" || strings.HasPrefix(line, "#") || !strings.HasPrefix(line, metric) {
147				continue
148			}
149			rest := strings.TrimSpace(strings.TrimPrefix(line, metric))
150			if strings.HasPrefix(rest, "{") {
151				if idx := strings.Index(rest, "}"); idx >= 0 {
152					rest = strings.TrimSpace(rest[idx+1:])
153				}
154			}
155			fields := strings.Fields(rest)
156			if len(fields) == 0 {
157				continue
158			}
159			val, err := strconv.ParseFloat(fields[0], 64)
160			if err == nil {
161				return val, true
162			}
163		}
164		return 0, false
165	}
